static bool sandbox3d_is_showcase_giraffe_entity(
    const sandbox3d_state* state,
    henka_entity entity)
{
    const char* name;

    if (state == NULL || state->scene == NULL || entity == HENKA_INVALID_ENTITY)
    {
        return false;
    }
    name = henka_scene_get_entity_name(state->scene, entity);
    return name != NULL && strncmp(name, "Showcase Giraffe ", sizeof("Showcase Giraffe ") - 1U) == 0;
}

static bool sandbox3d_is_showcase_rocket_entity(
    const sandbox3d_state* state,
    henka_entity entity)
{
    const char* name;

    if (state == NULL || state->scene == NULL || entity == HENKA_INVALID_ENTITY)
    {
        return false;
    }
    name = henka_scene_get_entity_name(state->scene, entity);
    return name != NULL && strncmp(name, "Showcase Rocket ", sizeof("Showcase Rocket ") - 1U) == 0;
}

static void sandbox3d_mark_generic_modeling_applied(
    sandbox3d_state* state,
    henka_entity entity)
{
    /* Modeling transactions can change the bounded authoring-flow height and
     * move the sticky project footer. Force the next frame to publish fresh
     * save/reload geometry instead of allowing automation or a user to reuse
     * a pre-edit hit target. */
    if (state != NULL)
    {
        state->native_authoring_project_controls_reported = false;
        state->native_authoring_project_controls_reported_entity = HENKA_INVALID_ENTITY;
        state->native_authoring_project_controls_reported_y = 0.0f;
    }
    if (sandbox3d_is_showcase_giraffe_entity(state, entity))
    {
        state->giraffe_generic_modeling_applied = true;
    }
    else if (sandbox3d_is_showcase_rocket_entity(state, entity))
    {
        state->rocket_generic_modeling_applied = true;
    }
}

static void sandbox3d_set_status(sandbox3d_state* state, bool warning, const char* message);
static void sandbox3d_cancel_active_modeling_operator_session(
    sandbox3d_state* state);

static bool sandbox3d_apply_authoring_bevel(
    sandbox3d_state* state,
    henka_entity entity,
    const char* display_name)
{
    char width_text[32];
    henka_result bevel_result = HENKA_SUCCESS;

    if (state == NULL || state->authoring_object == NULL || display_name == NULL)
    {
        return false;
    }
    (void)snprintf(
        width_text,
        sizeof(width_text),
        "%.9g",
        sandbox3d_authoring_object_get_bevel_width(state->authoring_object));
    sandbox3d_cancel_active_modeling_operator_session(state);
    bevel_result = sandbox3d_modeling_operator_begin(
        &state->modeling_operator,
        state->authoring_object,
        SANDBOX3D_MODELING_OPERATOR_BEVEL);
    if (bevel_result == HENKA_SUCCESS)
    {
        bevel_result = sandbox3d_modeling_operator_numeric_begin(
            &state->modeling_operator);
    }
    if (bevel_result == HENKA_SUCCESS)
    {
        bevel_result = sandbox3d_modeling_operator_numeric_append(
            &state->modeling_operator,
            width_text,
            strlen(width_text));
    }
    if (bevel_result == HENKA_SUCCESS)
    {
        bevel_result = sandbox3d_modeling_operator_numeric_commit(
            &state->modeling_operator);
    }
    if (bevel_result == HENKA_SUCCESS)
    {
        bevel_result = sandbox3d_modeling_operator_commit(
            &state->modeling_operator);
    }
    if (bevel_result != HENKA_SUCCESS && state->modeling_operator.active)
    {
        (void)sandbox3d_modeling_operator_cancel(&state->modeling_operator);
    }
    printf(
        "Native authoring bevel operator: name=%s result=%s width=%s selected_components=%zu.\n",
        display_name,
        henka_result_to_string(bevel_result),
        width_text,
        sandbox3d_authoring_object_get_selected_component_count(state->authoring_object));
    fflush(stdout);
    if (bevel_result != HENKA_SUCCESS)
    {
        sandbox3d_set_status(
            state,
            true,
            "Authoring bevel failed; the current source was retained.");
        return false;
    }
    {
        const henka_authoring_mesh_counts counts =
            henka_authoring_mesh_get_counts(
                sandbox3d_authoring_object_get_mesh(state->authoring_object));
        sandbox3d_mark_generic_modeling_applied(state, entity);
        printf(
            "Native authoring dogfood: bevel operator edited %s; vertices=%zu faces=%zu source_state=HENKA_NATIVE_EDITED_FIXTURE design_authority=EDITOR_DERIVED_FIXTURE.\n",
            display_name,
            counts.vertices,
            counts.faces);
        fflush(stdout);
    }
    sandbox3d_set_status(
        state,
        false,
        "Authoring bevel committed transactionally through the modeling operator.");
    return true;
}

static sandbox3d_modeling_operator_kind sandbox3d_authoring_extrude_operator_kind(
    const sandbox3d_state* state)
{
    const sandbox3d_authoring_selection_mode selection_mode =
        state == NULL || state->authoring_object == NULL
            ? SANDBOX3D_AUTHORING_SELECTION_FACE
            : sandbox3d_authoring_object_get_selection_mode(
                state->authoring_object);
    const henka_authoring_mesh* mesh;
    uint32_t component_id = HENKA_AUTHORING_INVALID_ID;
    const henka_authoring_edge* edge;

    if (state == NULL || state->authoring_object == NULL ||
        sandbox3d_authoring_object_get_selected_component_count(
            state->authoring_object) != 1U)
    {
        return SANDBOX3D_MODELING_OPERATOR_NONE;
    }
    if (selection_mode == SANDBOX3D_AUTHORING_SELECTION_VERTEX)
    {
        return SANDBOX3D_MODELING_OPERATOR_EXTRUDE;
    }
    if (selection_mode != SANDBOX3D_AUTHORING_SELECTION_EDGE ||
        sandbox3d_authoring_object_get_selected_component_at(
            state->authoring_object, 0U, &component_id) != HENKA_SUCCESS)
    {
        return SANDBOX3D_MODELING_OPERATOR_NONE;
    }
    mesh = sandbox3d_authoring_object_get_mesh(state->authoring_object);
    edge = mesh == NULL
        ? NULL
        : henka_authoring_mesh_get_edge(
            mesh, (henka_authoring_edge_id)component_id);
    if (edge == NULL)
    {
        return SANDBOX3D_MODELING_OPERATOR_NONE;
    }
    if (edge->face_count == 0U)
    {
        return SANDBOX3D_MODELING_OPERATOR_EXTRUDE;
    }
    if (edge->face_count == 1U)
    {
        return SANDBOX3D_MODELING_OPERATOR_EDGE_EXTRUDE;
    }
    return SANDBOX3D_MODELING_OPERATOR_NONE;
}

static henka_result sandbox3d_preview_authoring_extrude(
    sandbox3d_state* state,
    const char* amount_text)
{
    const sandbox3d_authoring_selection_mode selection_mode =
        state == NULL || state->authoring_object == NULL
            ? SANDBOX3D_AUTHORING_SELECTION_FACE
            : sandbox3d_authoring_object_get_selection_mode(
                state->authoring_object);
    const sandbox3d_modeling_operator_kind operator_kind =
        sandbox3d_authoring_extrude_operator_kind(state);
    henka_result result;

    if (state == NULL || state->authoring_object == NULL || amount_text == NULL ||
        sandbox3d_authoring_object_get_selected_component_count(
            state->authoring_object) != 1U ||
        (selection_mode != SANDBOX3D_AUTHORING_SELECTION_VERTEX &&
         selection_mode != SANDBOX3D_AUTHORING_SELECTION_EDGE) ||
        operator_kind == SANDBOX3D_MODELING_OPERATOR_NONE)
    {
        return HENKA_ERROR_INVALID_ARGUMENT;
    }
    sandbox3d_cancel_active_modeling_operator_session(state);
    result = sandbox3d_modeling_operator_begin(
        &state->modeling_operator,
        state->authoring_object,
        operator_kind);
    if (result == HENKA_SUCCESS &&
        operator_kind == SANDBOX3D_MODELING_OPERATOR_EXTRUDE)
    {
        result = sandbox3d_modeling_operator_set_axis(
            &state->modeling_operator,
            SANDBOX3D_MODELING_OPERATOR_AXIS_Y);
    }
    if (result == HENKA_SUCCESS)
    {
        result = sandbox3d_modeling_operator_numeric_begin(
            &state->modeling_operator);
    }
    if (result == HENKA_SUCCESS)
    {
        result = sandbox3d_modeling_operator_numeric_append(
            &state->modeling_operator,
            amount_text,
            strlen(amount_text));
    }
    if (result == HENKA_SUCCESS)
    {
        result = sandbox3d_modeling_operator_numeric_commit(
            &state->modeling_operator);
    }
    if (result != HENKA_SUCCESS && state->modeling_operator.active)
    {
        (void)sandbox3d_modeling_operator_cancel(&state->modeling_operator);
    }
    return result;
}

static bool sandbox3d_apply_authoring_face_delete(
    sandbox3d_state* state,
    henka_entity entity,
    const char* display_name)
{
    henka_result delete_result;

    if (state == NULL || state->authoring_object == NULL || display_name == NULL)
    {
        return false;
    }
    delete_result = sandbox3d_authoring_object_delete_selected_faces(
        state->authoring_object);
    printf(
        "Native authoring face delete request: name=%s result=%s selected_components=%zu.\n",
        display_name,
        henka_result_to_string(delete_result),
        sandbox3d_authoring_object_get_selected_component_count(state->authoring_object));
    fflush(stdout);
    if (delete_result != HENKA_SUCCESS)
    {
        sandbox3d_set_status(
            state,
            true,
            "Authoring face delete rejected; at least one valid face and the current source were retained.");
        return false;
    }
    {
        const henka_authoring_mesh_counts counts =
            henka_authoring_mesh_get_counts(
                sandbox3d_authoring_object_get_mesh(state->authoring_object));
        sandbox3d_mark_generic_modeling_applied(state, entity);
        printf(
            "Native authoring dogfood: selected faces deleted from %s; vertices=%zu faces=%zu source_state=HENKA_NATIVE_EDITED_FIXTURE design_authority=EDITOR_DERIVED_FIXTURE.\n",
            display_name,
            counts.vertices,
            counts.faces);
        fflush(stdout);
    }
    sandbox3d_set_status(
        state,
        false,
        "Selected faces deleted and evaluated into the scene.");
    return true;
}

static void sandbox3d_mark_asset_specific_preset_applied(
    sandbox3d_state* state,
    henka_entity entity)
{
    if (sandbox3d_is_showcase_giraffe_entity(state, entity))
    {
        state->giraffe_asset_specific_preset_applied = true;
    }
    else if (sandbox3d_is_showcase_rocket_entity(state, entity))
    {
        state->rocket_asset_specific_preset_applied = true;
    }
}

static const char* sandbox3d_showcase_provenance(
    const sandbox3d_state* state,
    henka_entity entity)
{
    if ((sandbox3d_is_showcase_giraffe_entity(state, entity) && state->giraffe_generic_modeling_applied) ||
        (sandbox3d_is_showcase_rocket_entity(state, entity) && state->rocket_generic_modeling_applied))
    {
        return "HENKA_NATIVE_EDITED_FIXTURE";
    }
    return "GENERATED_TEST_FIXTURE";
}

