static henka_terrain_region_id sandbox3d_terrain_region_at_position(
    const henka_terrain_world_desc* world_desc,
    henka_vec3 position)
{
    int32_t region_x;
    int32_t region_z;
    if (world_desc == NULL || world_desc->region_edge_meters == 0U)
    {
        return (henka_terrain_region_id){0, 0};
    }
    region_x = (int32_t)floorf(position.x / (float)world_desc->region_edge_meters);
    region_z = (int32_t)floorf(position.z / (float)world_desc->region_edge_meters);
    if (region_x < 0)
    {
        region_x = 0;
    }
    if (region_z < 0)
    {
        region_z = 0;
    }
    if ((uint32_t)region_x >= world_desc->regions_across)
    {
        region_x = (int32_t)world_desc->regions_across - 1;
    }
    if ((uint32_t)region_z >= world_desc->regions_down)
    {
        region_z = (int32_t)world_desc->regions_down - 1;
    }
    return (henka_terrain_region_id){region_x, region_z};
}

static henka_terrain_stream_observer sandbox3d_make_terrain_stream_observer(
    const henka_terrain_world_desc* world_desc,
    henka_vec3 position)
{
    return (henka_terrain_stream_observer){
        1U,
        sandbox3d_terrain_region_at_position(world_desc, position),
        SANDBOX3D_TERRAIN_STREAM_CPU_RADIUS_REGIONS,
        SANDBOX3D_TERRAIN_STREAM_PHYSICS_RADIUS_REGIONS,
        SANDBOX3D_TERRAIN_STREAM_RENDER_RADIUS_REGIONS,
        SANDBOX3D_TERRAIN_STREAM_UNLOAD_RADIUS_REGIONS};
}

static henka_result sandbox3d_update_terrain_streaming(sandbox3d_state* state)
{
    henka_terrain_world_desc world_desc;
    henka_terrain_stream_observer observer;
    henka_result result;
    if (state == NULL || state->terrain_streamer == NULL || state->terrain_world == NULL)
    {
        return HENKA_SUCCESS;
    }
    if (henka_terrain_world_get_desc(state->terrain_world, &world_desc) != HENKA_SUCCESS)
    {
        return HENKA_ERROR_INVALID_ARGUMENT;
    }
    observer = sandbox3d_make_terrain_stream_observer(
        &world_desc, state->camera.position);
    result = henka_terrain_streamer_update_observer(state->terrain_streamer, &observer);
    if (result != HENKA_SUCCESS)
    {
        return result;
    }
    result = henka_terrain_streamer_pump(state->terrain_streamer, 2U);
    if (result != HENKA_SUCCESS)
    {
        return result;
    }
    if (state->terrain_collision_runtime != NULL)
    {
        result = henka_terrain_collision_runtime_set_focus(
            state->terrain_collision_runtime, observer.center_region);
        if (result != HENKA_SUCCESS)
        {
            return result;
        }
        result = henka_terrain_collision_runtime_sync_residency(
            state->terrain_collision_runtime);
        if (result != HENKA_SUCCESS)
        {
            return result;
        }
        result = henka_terrain_collision_runtime_pump(
            state->terrain_collision_runtime, 2U);
        if (result != HENKA_SUCCESS)
        {
            return result;
        }
    }
    return HENKA_SUCCESS;
}

static void sandbox3d_generate_terrain_fixture(
    const henka_terrain_layout* layout,
    henka_terrain_region_id region_id,
    henka_terrain_sample* samples)
{
    uint32_t sample_z;
    uint32_t sample_x;
    const uint32_t region_sample_edge = layout->samples_per_region_edge - 1U;

    for (sample_z = 0U; sample_z < layout->samples_per_region_edge; ++sample_z)
    {
        for (sample_x = 0U; sample_x < layout->samples_per_region_edge; ++sample_x)
        {
            henka_terrain_sample* sample = &samples[
                (size_t)sample_z * layout->samples_per_region_edge + sample_x];
            const float x = (float)((int64_t)region_id.x * region_sample_edge + sample_x);
            const float z = (float)((int64_t)region_id.z * region_sample_edge + sample_z);
            const float rolling = 650.0f * sinf(x * 0.045f) * cosf(z * 0.037f);
            const float valley_distance_x = (x - 256.0f) / 126.0f;
            const float valley_distance_z = (z - 320.0f) / 154.0f;
            const float valley = expf(-0.5f *
                (valley_distance_x * valley_distance_x + valley_distance_z * valley_distance_z));
            const float ridge_distance = (x - 410.0f) / 54.0f;
            const float ridge = expf(-0.5f * ridge_distance * ridge_distance);
            const float cliff = tanhf((x - 372.0f) / 15.0f);
            const float height_millimeters = 1200.0f + rolling -
                valley * 1700.0f + ridge * 2800.0f + cliff * 2400.0f;
            const float slope_signal = fminf(
                1.0f,
                fabsf(sinf(x * 0.045f) * cosf(z * 0.037f)) +
                fabsf(cliff) * 0.45f + ridge * 0.35f);
            const int rock_weight = 20 + (int)lroundf(slope_signal * 130.0f + ridge * 55.0f);
            const int wet_weight = 10 + (int)lroundf(valley * 120.0f);
            const int dirt_weight = 35 + (int)lroundf(slope_signal * 42.0f);
            const int grass_weight = 255 - rock_weight - wet_weight - dirt_weight;

            sample->height_millimeters = (int32_t)lroundf(height_millimeters);
            sample->material_weights[0] = (uint8_t)(grass_weight > 1 ? grass_weight : 1);
            sample->material_weights[1] = (uint8_t)(dirt_weight > 1 ? dirt_weight : 1);
            sample->material_weights[2] = (uint8_t)(rock_weight > 1 ? rock_weight : 1);
            sample->material_weights[3] = (uint8_t)(wet_weight > 1 ? wet_weight : 1);
            (void)henka_terrain_normalize_weights(sample->material_weights);
        }
    }
}

static unsigned char sandbox3d_encode_realism_texture_channel(float value)
{
    return (unsigned char)lroundf(fmaxf(0.0f, fminf(255.0f, value)));
}

static void sandbox3d_generate_realism_detail_textures(
    unsigned char* normal_pixels,
    unsigned char* macro_variation_pixels,
    unsigned char* wood_grain_pixels,
    unsigned char* wet_dry_roughness_pixels)
{
    uint32_t x;
    uint32_t y;

    if (normal_pixels == NULL || macro_variation_pixels == NULL ||
        wood_grain_pixels == NULL || wet_dry_roughness_pixels == NULL)
    {
        return;
    }
    for (y = 0U; y < SANDBOX3D_REALISM_TEXTURE_EDGE; ++y)
    {
        for (x = 0U; x < SANDBOX3D_REALISM_TEXTURE_EDGE; ++x)
        {
            const float u = ((float)x + 0.5f) /
                (float)SANDBOX3D_REALISM_TEXTURE_EDGE;
            const float v = ((float)y + 0.5f) /
                (float)SANDBOX3D_REALISM_TEXTURE_EDGE;
            const float normal_x = 0.08f * sinf(
                2.0f * HENKA_PI * (u * 3.0f + v * 1.5f)) +
                0.035f * cosf(2.0f * HENKA_PI * (u * 7.0f - v * 2.0f));
            const float normal_y = 0.07f * cosf(
                2.0f * HENKA_PI * (v * 4.0f - u * 1.25f)) +
                0.03f * sinf(2.0f * HENKA_PI * (u * 2.0f + v * 8.0f));
            const float normal_z = sqrtf(fmaxf(
                0.0f, 1.0f - normal_x * normal_x - normal_y * normal_y));
            const float macro_signal = 0.5f + 0.5f * sinf(
                2.0f * HENKA_PI * (u * 2.5f + 0.35f * sinf(v * 2.0f * HENKA_PI)));
            const float grain_signal = 0.5f + 0.5f * sinf(
                2.0f * HENKA_PI * (u * 3.0f + 0.35f * sinf(v * 2.0f * HENKA_PI * 1.5f)));
            const float wet_signal = 0.5f + 0.5f * sinf(
                2.0f * HENKA_PI * (v * 1.25f + 0.25f * sinf(u * 2.0f * HENKA_PI * 3.0f)));
            const size_t pixel = ((size_t)y * SANDBOX3D_REALISM_TEXTURE_EDGE + x) *
                SANDBOX3D_REALISM_TEXTURE_CHANNEL_COUNT;

            normal_pixels[pixel + 0U] = sandbox3d_encode_realism_texture_channel(
                128.0f + normal_x * 127.0f);
            normal_pixels[pixel + 1U] = sandbox3d_encode_realism_texture_channel(
                128.0f + normal_y * 127.0f);
            normal_pixels[pixel + 2U] = sandbox3d_encode_realism_texture_channel(
                normal_z * 127.0f + 128.0f);
            normal_pixels[pixel + 3U] = 255U;

            macro_variation_pixels[pixel + 0U] = sandbox3d_encode_realism_texture_channel(
                96.0f + macro_signal * 82.0f);
            macro_variation_pixels[pixel + 1U] = sandbox3d_encode_realism_texture_channel(
                58.0f + macro_signal * 54.0f);
            macro_variation_pixels[pixel + 2U] = sandbox3d_encode_realism_texture_channel(
                32.0f + macro_signal * 32.0f);
            macro_variation_pixels[pixel + 3U] = 255U;

            wood_grain_pixels[pixel + 0U] = sandbox3d_encode_realism_texture_channel(
                96.0f + grain_signal * 48.0f);
            wood_grain_pixels[pixel + 1U] = sandbox3d_encode_realism_texture_channel(
                46.0f + grain_signal * 28.0f);
            wood_grain_pixels[pixel + 2U] = sandbox3d_encode_realism_texture_channel(
                20.0f + grain_signal * 16.0f);
            wood_grain_pixels[pixel + 3U] = 255U;

            wet_dry_roughness_pixels[pixel + 0U] = 255U;
            wet_dry_roughness_pixels[pixel + 1U] = sandbox3d_encode_realism_texture_channel(
                34.0f + wet_signal * 206.0f);
            wet_dry_roughness_pixels[pixel + 2U] = 255U;
            wet_dry_roughness_pixels[pixel + 3U] = 255U;
        }
    }
}

static uint32_t sandbox3d_terrain_texture_hash(
    uint32_t x,
    uint32_t z,
    uint32_t layer)
{
    uint32_t value = x * 374761393U ^ z * 668265263U ^ layer * 2246822519U;
    value ^= value >> 13U;
    value *= 1274126177U;
    value ^= value >> 16U;
    return value;
}

static float sandbox3d_terrain_texture_value_noise(
    uint32_t x,
    uint32_t z,
    uint32_t layer,
    uint32_t cell_size)
{
    const uint32_t period = SANDBOX3D_TERRAIN_TEXTURE_SIZE;
    const uint32_t x0 = (x / cell_size) * cell_size;
    const uint32_t z0 = (z / cell_size) * cell_size;
    const uint32_t x1 = (x0 + cell_size) % period;
    const uint32_t z1 = (z0 + cell_size) % period;
    const float x_fraction = (float)(x % cell_size) / (float)cell_size;
    const float z_fraction = (float)(z % cell_size) / (float)cell_size;
    const float x_smooth = x_fraction * x_fraction * (3.0f - 2.0f * x_fraction);
    const float z_smooth = z_fraction * z_fraction * (3.0f - 2.0f * z_fraction);
    const float lower = (float)(sandbox3d_terrain_texture_hash(x0, z0, layer) & 0xffffU) / 65535.0f *
        (1.0f - x_smooth) +
        (float)(sandbox3d_terrain_texture_hash(x1, z0, layer) & 0xffffU) / 65535.0f * x_smooth;
    const float upper = (float)(sandbox3d_terrain_texture_hash(x0, z1, layer) & 0xffffU) / 65535.0f *
        (1.0f - x_smooth) +
        (float)(sandbox3d_terrain_texture_hash(x1, z1, layer) & 0xffffU) / 65535.0f * x_smooth;
    return lower * (1.0f - z_smooth) + upper * z_smooth;
}

static float sandbox3d_terrain_texture_height(
    uint32_t x,
    uint32_t z,
    uint32_t layer)
{
    const uint32_t period = SANDBOX3D_TERRAIN_TEXTURE_SIZE;
    const uint32_t wrapped_x = x % period;
    const uint32_t wrapped_z = z % period;
    const float fine = sandbox3d_terrain_texture_value_noise(wrapped_x, wrapped_z, layer, 4U);
    const float medium = sandbox3d_terrain_texture_value_noise(wrapped_x, wrapped_z, layer + 17U, 12U);
    const float broad = sandbox3d_terrain_texture_value_noise(wrapped_x, wrapped_z, layer + 31U, 32U);
    return (fine - 0.5f) * 0.62f + (medium - 0.5f) * 0.29f + (broad - 0.5f) * 0.16f;
}

static henka_result sandbox3d_generate_stream_region(
    void* user_data,
    henka_terrain_region_id region_id,
    const henka_terrain_world_desc* world_desc,
    const henka_terrain_layout* layout,
    henka_terrain_sample* samples,
    size_t sample_count)
{
    (void)user_data;
    if (world_desc == NULL || layout == NULL || samples == NULL ||
        sample_count != layout->samples_per_region ||
        !henka_terrain_region_id_is_valid(world_desc, region_id))
    {
        return HENKA_ERROR_INVALID_ARGUMENT;
    }
    sandbox3d_generate_terrain_fixture(layout, region_id, samples);
    return HENKA_SUCCESS;
}

static henka_result sandbox3d_seed_terrain_fixture_region(
    henka_terrain_storage* storage,
    const henka_terrain_layout* layout,
    henka_terrain_region_id region_id,
    uint64_t transaction_id,
    henka_terrain_sample* samples,
    bool overwrite_existing)
{
    henka_terrain_region_storage_info info;
    henka_result result;

    sandbox3d_generate_terrain_fixture(layout, region_id, samples);
    result = overwrite_existing
        ? HENKA_ERROR_ASSET_SOURCE
        : henka_terrain_storage_load_region(
            storage, region_id, &info, samples, layout->samples_per_region);
    if (result == HENKA_SUCCESS)
    {
        return HENKA_SUCCESS;
    }
    if (result != HENKA_ERROR_ASSET_SOURCE)
    {
        return result;
    }
    result = henka_terrain_storage_begin(storage, transaction_id);
    if (result == HENKA_SUCCESS)
    {
        result = henka_terrain_storage_write_region(
            storage, region_id, 1U, 1U, samples, layout->samples_per_region);
    }
    if (result == HENKA_SUCCESS)
    {
        result = henka_terrain_storage_commit(storage, transaction_id);
    }
    if (result != HENKA_SUCCESS)
    {
        (void)henka_terrain_storage_abort(storage, transaction_id);
    }
    return result;
}

