static bool sandbox3d_parse_capture_exposure(
    const char* value,
    float* out_exposure)
{
    char* end = NULL;
    float exposure;

    if (value == NULL || out_exposure == NULL || value[0] == '\0')
    {
        return false;
    }
    exposure = strtof(value, &end);
    if (end == value || end == NULL || *end != '\0' ||
        !isfinite(exposure) || exposure < -16.0f || exposure > 16.0f)
    {
        return false;
    }
    *out_exposure = exposure;
    return true;
}

static bool sandbox3d_parse_loop_cut_factor(
    const char* text,
    float* out_factor)
{
    char* end = NULL;
    float factor;

    if (text == NULL || out_factor == NULL || text[0] == '\0')
    {
        return false;
    }

    errno = 0;
    factor = strtof(text, &end);
    if (errno == ERANGE || end == NULL || *end != '\0' ||
        !isfinite(factor) || factor <= 0.0f || factor >= 1.0f)
    {
        return false;
    }

    *out_factor = factor;
    return true;
}

static bool sandbox3d_parse_loop_cut_count(
    const char* text,
    size_t* out_count)
{
    char* end = NULL;
    unsigned long count;

    if (text == NULL || out_count == NULL || text[0] == '\0')
    {
        return false;
    }

    errno = 0;
    count = strtoul(text, &end, 10);
    if (errno == ERANGE || end == NULL || *end != '\0' || count == 0UL ||
        count > (unsigned long)SANDBOX3D_MAX_LOOP_CUT_COUNT)
    {
        return false;
    }

    *out_count = (size_t)count;
    return true;
}

static bool sandbox3d_parse_edge_slide_factor(
    const char* text,
    float* out_factor)
{
    char* end = NULL;
    float factor;

    if (text == NULL || out_factor == NULL || text[0] == '\0')
    {
        return false;
    }

    errno = 0;
    factor = strtof(text, &end);
    if (errno == ERANGE || end == NULL || *end != '\0' ||
        !isfinite(factor) || factor <= -1.0f || factor >= 1.0f)
    {
        return false;
    }

    *out_factor = factor;
    return true;
}

static bool sandbox3d_parse_finite_float(
    const char* text,
    float* out_value)
{
    char* end = NULL;
    float value;

    if (text == NULL || out_value == NULL || text[0] == '\0')
    {
        return false;
    }

    errno = 0;
    value = strtof(text, &end);
    if (errno == ERANGE || end == NULL || *end != '\0' || !isfinite(value))
    {
        return false;
    }

    *out_value = value;
    return true;
}

static henka_viewport_shading_mode
sandbox3d_get_saved_viewport_shading_mode(
    const sandbox3d_state* state)
{
    henka_viewport_shading_mode mode;
    const char* value;

    if (state == NULL || state->settings == NULL)
    {
        return HENKA_VIEWPORT_SHADING_SOLID;
    }

    if (henka_settings_has_key(
            state->settings,
            g_setting_key_viewport_shading_mode))
    {
        value = henka_settings_get_string(
            state->settings,
            g_setting_key_viewport_shading_mode,
            "solid");
        if (henka_viewport_shading_mode_parse(
                value,
                &mode) == HENKA_SUCCESS)
        {
            return mode;
        }

        HENKA_LOG_WARN(
            "Invalid viewport shading setting '%s'; Solid was restored.",
            value);
        return HENKA_VIEWPORT_SHADING_SOLID;
    }

    return henka_settings_get_bool(
        state->settings,
        g_setting_key_wireframe_enabled,
        false) ?
        HENKA_VIEWPORT_SHADING_WIREFRAME :
        HENKA_VIEWPORT_SHADING_SOLID;
}
